-- Domain model (T-01, issue #24): catalog, inventory, orders, simulated payments and audit.
--
-- Generated by Prisma 7.10 (`prisma migrate dev --create-only` / `prisma migrate diff --script`)
-- and then hand edited ONLY for what the Prisma schema cannot express. Every hand edit is marked
-- with "HAND EDIT":
--   1. the `order_code_seq` sequence and the `next_order_code()` function (default of orders.code);
--   2. CHECK constraints (allowed values of status/fulfillment/category/reason/role/action
--      columns, non-negative stock, positive prices, line totals, delivery data, note length and
--      ledger arithmetic).
-- Allowed values mirror the `as const` lists of @repo/shared (src/domain): keep both in sync.

-- CreateExtension
CREATE EXTENSION IF NOT EXISTS "pg_trgm";

