-- HAND EDIT (1/2): human readable order codes ("P-000001"). lpad never truncates: past 999999
-- the code simply grows ("P-1000000"), so it stays unique. Sequence values are never reused,
-- so gaps are possible (rolled back transactions) and expected.
CREATE SEQUENCE "order_code_seq" AS BIGINT START WITH 1 INCREMENT BY 1;

CREATE FUNCTION "next_order_code"() RETURNS TEXT
LANGUAGE sql VOLATILE
AS $$
  SELECT 'P-' || lpad(n::text, greatest(6, length(n::text)), '0')
  FROM nextval('order_code_seq') AS n
$$;

