-- HAND EDIT (2/2): CHECK constraints. Prisma does not model CHECK constraints, so
-- `prisma migrate diff` neither creates nor drops them.

-- products: category in PRODUCT_CATEGORIES, positive CLP price, non-empty business keys.
ALTER TABLE "products"
  ADD CONSTRAINT "products_category_check" CHECK ("category" IN ('cardiovascular', 'salud-mental', 'analgesicos', 'suplementos', 'digestivo', 'otros')),
  ADD CONSTRAINT "products_price_clp_check" CHECK ("price_clp" > 0),
  ADD CONSTRAINT "products_sku_check" CHECK (length(btrim("sku")) > 0),
  ADD CONSTRAINT "products_commercial_name_check" CHECK (length(btrim("commercial_name")) > 0);

-- inventory_items: stock can never be negative (RNF-08); threshold and version non-negative.
ALTER TABLE "inventory_items"
  ADD CONSTRAINT "inventory_items_on_hand_check" CHECK ("on_hand" >= 0),
  ADD CONSTRAINT "inventory_items_low_stock_threshold_check" CHECK ("low_stock_threshold" >= 0),
  ADD CONSTRAINT "inventory_items_version_check" CHECK ("version" >= 0);

-- stock_movements: reason in STOCK_MOVEMENT_REASONS, consistent ledger arithmetic, direction
-- per reason (a sale subtracts, a restore or receipt adds) and order-bound reasons carry the order.
ALTER TABLE "stock_movements"
  ADD CONSTRAINT "stock_movements_reason_check" CHECK ("reason" IN ('sale', 'cancellation_restore', 'receipt', 'adjustment')),
  ADD CONSTRAINT "stock_movements_delta_check" CHECK ("delta" <> 0),
  ADD CONSTRAINT "stock_movements_quantities_check" CHECK ("quantity_before" >= 0 AND "quantity_after" >= 0 AND "quantity_after" = "quantity_before" + "delta"),
  ADD CONSTRAINT "stock_movements_direction_check" CHECK (
    ("reason" = 'sale' AND "delta" < 0)
    OR ("reason" IN ('cancellation_restore', 'receipt') AND "delta" > 0)
    OR "reason" = 'adjustment'
  ),
  ADD CONSTRAINT "stock_movements_order_check" CHECK ("reason" NOT IN ('sale', 'cancellation_restore') OR "order_id" IS NOT NULL);

-- orders: status in ORDER_STATUSES, fulfillment in FULFILLMENT_TYPES; only a draft (or an order
-- cancelled while draft) may lack a fulfillment; delivery requires sector, address reference and
-- contact alias (HU-04, D-04) and any other fulfillment carries no delivery data.
ALTER TABLE "orders"
  ADD CONSTRAINT "orders_status_check" CHECK ("status" IN ('draft', 'pending_payment', 'payment_validated', 'payment_rejected', 'in_preparation', 'ready_for_pickup', 'in_transit', 'delivered', 'not_delivered', 'cancelled')),
  ADD CONSTRAINT "orders_fulfillment_check" CHECK ("fulfillment" IS NULL OR "fulfillment" IN ('pickup', 'delivery')),
  ADD CONSTRAINT "orders_fulfillment_required_check" CHECK ("status" IN ('draft', 'cancelled') OR "fulfillment" IS NOT NULL),
  ADD CONSTRAINT "orders_delivery_details_check" CHECK (
    CASE WHEN "fulfillment" = 'delivery'
      THEN "delivery_sector" IS NOT NULL AND "delivery_address_reference" IS NOT NULL AND "delivery_contact_alias" IS NOT NULL
      ELSE "delivery_sector" IS NULL AND "delivery_address_reference" IS NULL AND "delivery_contact_alias" IS NULL AND "delivery_instructions" IS NULL
    END
  ),
  ADD CONSTRAINT "orders_total_clp_check" CHECK ("total_clp" >= 0),
  ADD CONSTRAINT "orders_version_check" CHECK ("version" >= 0);

-- order_lines: 1..99 units, positive unit price snapshot, consistent line total.
ALTER TABLE "order_lines"
  ADD CONSTRAINT "order_lines_quantity_check" CHECK ("quantity" BETWEEN 1 AND 99),
  ADD CONSTRAINT "order_lines_unit_price_clp_check" CHECK ("unit_price_clp" > 0),
  ADD CONSTRAINT "order_lines_line_total_clp_check" CHECK ("line_total_clp" = "quantity" * "unit_price_clp");

-- order_status_events: statuses in ORDER_STATUSES (from_status null only for the creation
-- event), actor_role in ACTOR_ROLES and a note of at most 200 characters.
ALTER TABLE "order_status_events"
  ADD CONSTRAINT "order_status_events_from_status_check" CHECK ("from_status" IS NULL OR "from_status" IN ('draft', 'pending_payment', 'payment_validated', 'payment_rejected', 'in_preparation', 'ready_for_pickup', 'in_transit', 'delivered', 'not_delivered', 'cancelled')),
  ADD CONSTRAINT "order_status_events_to_status_check" CHECK ("to_status" IN ('draft', 'pending_payment', 'payment_validated', 'payment_rejected', 'in_preparation', 'ready_for_pickup', 'in_transit', 'delivered', 'not_delivered', 'cancelled')),
  ADD CONSTRAINT "order_status_events_actor_role_check" CHECK ("actor_role" IN ('resident', 'operator', 'admin', 'system')),
  ADD CONSTRAINT "order_status_events_note_check" CHECK ("note" IS NULL OR char_length("note") <= 200);

-- payments: status in PAYMENT_STATUSES, positive amount, non-empty idempotency key.
ALTER TABLE "payments"
  ADD CONSTRAINT "payments_status_check" CHECK ("status" IN ('approved', 'rejected', 'stock_conflict')),
  ADD CONSTRAINT "payments_amount_clp_check" CHECK ("amount_clp" > 0),
  ADD CONSTRAINT "payments_idempotency_key_check" CHECK (length(btrim("idempotency_key")) > 0);

-- audit_logs: actor_role in ACTOR_ROLES, action in AUDIT_ACTIONS and a non-empty entity.
ALTER TABLE "audit_logs"
  ADD CONSTRAINT "audit_logs_actor_role_check" CHECK ("actor_role" IN ('resident', 'operator', 'admin', 'system')),
  ADD CONSTRAINT "audit_logs_action_check" CHECK ("action" IN ('order.transition', 'stock.sale', 'stock.restore', 'payment.stock_conflict', 'user.role_change')),
  ADD CONSTRAINT "audit_logs_entity_check" CHECK (length(btrim("entity_type")) > 0 AND length(btrim("entity_id")) > 0);
